<script setup>
import { computed, onMounted, reactive, ref } from 'vue';
import api from './api';

const token = ref(localStorage.getItem('sanbenjamin-token'));
const user = ref(JSON.parse(localStorage.getItem('sanbenjamin-user') || 'null'));
const section = ref('dashboard');
const loading = ref(false);
const error = ref('');
const notice = ref('');
const loginForm = reactive({ username: 'hector', password: 'hector123' });
const loginError = ref('');
const categories = ref([]), products = ref([]), customers = ref([]), suppliers = ref([]), inventory = ref([]), lots = ref([]), movements = ref([]), summary = ref(null), monthly = ref(null), quotations = ref([]), payments = ref([]), installments = ref([]), audit = ref([]), sales = ref([]), purchases = ref([]), expenses = ref([]), users = ref([]), settings = ref([]);
const twoFactor = ref(null);
const customerHistory = ref(null);
const categoryForm = reactive({ name: '', description: '' });
const customerForm = reactive({ name: '', document: '', phone: '', address: '' });
const supplierForm = reactive({ name: '', document: '', phone: '', address: '' });
const productForm = reactive({ code: '', name: '', salePrice: 0, purchaseCost: 0, minStock: 0, categoryId: '' });
const quotationForm = reactive({ customerId: '', productId: '', quantity: 1, unitPrice: 0 });
const quotationEditing = ref(null);
const reportTab = ref('summary');
const userEditing = ref(null);
const userEditForm = reactive({ name: '', username: '', password: '', role: 'OPERATOR', active: true });
const auditFilter = ref('');
const documentFilters = reactive({ search: '', documentType: '', commercial: '', year: new Date().getFullYear() });
const inventoryFilters = reactive({ search: '', stockFrom: '', stockTo: '' });
const userForm = reactive({ name: '', username: '', password: '', role: 'OPERATOR' });
const settingForm = reactive({ key: '', value: '' });
const historyForm = reactive({ customerId: '', amount: 0, type: 'CASH', reference: '' });
const lotForm = reactive({ productId: '', code: '', expiryDate: '', quantity: 0 });
const adjustmentForm = reactive({ productId: '', lotId: '', type: 'ADJUSTMENT', quantity: 0, reference: '' });
const expenseForm = reactive({ description: '', category: '', amount: 0, expenseDate: '' });
const operation = reactive({ personId: '', items: [{ productId: '', quantity: 1, price: 0 }] });
const operationMeta = reactive({ documentType: 'INVOICE', stockMode: 'NORMAL', date: new Date().toISOString().slice(0, 10), number: '', invoice: '', paymentPlan: 'CASH' });
const editing = ref(null);
const catalogEditing = ref(null);
const catalogEditForm = reactive({ name: '', description: '', code: '', salePrice: 0, purchaseCost: 0, minStock: 0, categoryId: '', document: '', phone: '', address: '' });
const lotEditing = ref(null);
const editForm = reactive({ personId: '', items: [] });
const receiptPreview = ref(null);
const paymentForm = reactive({ documentId: '', documentType: 'sale', amount: 0, type: 'CASH', reference: '' });
const installmentForm = reactive({ documentId: '', documentType: 'sale', amount: 0, dueDate: '' });
const twoFactorToken = ref('');
const commercialName = ref(localStorage.getItem('sanbenjamin-commercial') || 'San Benjamin');
const isDark = ref(localStorage.getItem('theme-mode') === 'dark');
const commercialConfirmed = ref(Boolean(localStorage.getItem('sanbenjamin-commercial-selected')));
const exchangeRate = ref(11.75);
const commercialNit = computed(() => commercialName.value === 'Supra Medic' ? '1031388011' : '411168020');
const dashboardAlertIndex = ref(0);
const isLogged = computed(() => Boolean(token.value));
const operationTotal = computed(() => operation.items.reduce((total, item) => total + Number(item.quantity || 0) * Number(item.price || 0), 0));
const pendingStockDocuments = computed(() => purchases.value.filter((document) => document.status === 'PENDING').length + sales.value.filter((document) => document.status === 'PENDING').length);
const receivableAmount = computed(() => installments.value.filter((item) => item.status === 'PENDING').reduce((total, item) => total + Number(item.amount || item.balance || item.pendingAmount || 0), 0));
const selectedQuotationProduct = computed(() => products.value.find((product) => product.id === Number(quotationForm.productId)) || null);
const quotationTotal = computed(() => Number(quotationForm.quantity || 0) * Number(quotationForm.unitPrice || 0));
const expiringLots = computed(() => { const limit = Date.now() + 30 * 86400000; return lots.value.filter((lot) => lot.expiryDate && new Date(lot.expiryDate).getTime() <= limit); });
const title = computed(() => ({ dashboard: 'Dashboard', reports: 'Reportes', products: 'Productos', categories: 'Categorías', customers: 'Clientes', suppliers: 'Proveedores', inventory: 'Inventario', lots: 'Lotes', movements: 'Kardex', quotations: 'Cotizaciones', payments: 'Pagos', installments: 'Cuotas', sales: 'Ventas', purchases: 'Compras', expenses: 'Gastos operativos', history: 'Historial de clientes', audit: 'Auditoría', security: 'Seguridad 2FA', users: 'Usuarios', settings: 'Configuración', purchase: 'Registro de compras', sale: 'Registro de ventas' }[section.value]));

async function login() {
  loginError.value = '';
  try { const { data } = await api.post('/auth/login', loginForm); token.value = data.accessToken; user.value = data.user; localStorage.setItem('sanbenjamin-token', token.value); localStorage.setItem('sanbenjamin-user', JSON.stringify(user.value)); await loadData(); }
  catch (e) { loginError.value = e.response?.data?.message || 'No fue posible iniciar sesión'; }
}
function logout() { localStorage.removeItem('sanbenjamin-token'); localStorage.removeItem('sanbenjamin-user'); localStorage.removeItem('sanbenjamin-commercial-selected'); token.value = null; user.value = null; commercialConfirmed.value = false; section.value = 'dashboard'; }
function select(value) { section.value = value; notice.value = ''; error.value = ''; }
function changeCommercial() { localStorage.setItem('sanbenjamin-commercial', commercialName.value); notice.value = `Contexto comercial: ${commercialName.value}`; }
function confirmCommercial() { localStorage.setItem('sanbenjamin-commercial', commercialName.value); localStorage.setItem('sanbenjamin-commercial-selected', '1'); commercialConfirmed.value = true; }
function toggleTheme() { isDark.value = !isDark.value; localStorage.setItem('theme-mode', isDark.value ? 'dark' : 'light'); document.documentElement.classList.toggle('theme-dark', isDark.value); }
const dashboardAlerts = computed(() => {
  const alerts = [];
  const low = inventory.value.filter((p) => Number(p.stock) <= Number(p.minStock));
  if (low.length) alerts.push({ type: 'stock', title: 'Stock bajo', detail: `${low.length} producto(s) están en el mínimo o por debajo`, count: low.length });
  const today = new Date();
  const expiring = lots.value.filter((lot) => lot.expiryDate && new Date(lot.expiryDate) <= new Date(today.getTime() + 30 * 86400000));
  if (expiring.length) alerts.push({ type: 'expiry', title: 'Lotes por vencer', detail: 'Existen lotes dentro del rango de alerta', count: expiring.length });
  const overdue = installments.value.filter((i) => i.status === 'PENDING' && i.dueDate && new Date(i.dueDate) < today);
  if (overdue.length) alerts.push({ type: 'dues', title: 'Cuotas vencidas', detail: 'Revisar cuentas pendientes de cobro', count: overdue.length });
  return alerts;
});
const activeDashboardAlert = computed(() => dashboardAlerts.value[dashboardAlertIndex.value] || null);
const filteredAudit = computed(() => { const term = auditFilter.value.trim().toLowerCase(); return term ? audit.value.filter((event) => `${event.action} ${event.entity} ${event.details || ''} ${event.user?.username || ''}`.toLowerCase().includes(term)) : audit.value; });
function closeDashboardAlert() { dashboardAlertIndex.value += 1; }
async function loadData() {
  if (!token.value) return; loading.value = true;
  try {
    const requests = [
      api.get('/categories'), api.get('/products'), api.get('/customers'), api.get('/suppliers'),
      api.get('/inventory'), api.get('/reports/summary'), api.get('/reports/monthly'), api.get('/quotations'),
      api.get('/payments'), api.get('/installments'), api.get('/sales'), api.get('/purchases'),
      api.get('/inventory/lots'), api.get('/inventory/movements'), api.get('/expenses'),
    ];
    if (user.value?.role === 'ADMIN') requests.push(api.get('/audit'), api.get('/users'), api.get('/settings'));
    const [a, b, c, d, e, f, monthlyReport, g, h, i, j, k, l, m, n, o, p, q, r, s, t] = await Promise.all(requests);
    categories.value=a.data; products.value=b.data; customers.value=c.data; suppliers.value=d.data; inventory.value=e.data;
    summary.value=f.data; monthly.value=monthlyReport.data; quotations.value=g.data; payments.value=h.data;
    installments.value=i.data; sales.value=j.data; purchases.value=k.data; lots.value=l.data; movements.value=m.data; expenses.value=n.data;
    if (user.value?.role === 'ADMIN') { audit.value=o.data; users.value=p.data; settings.value=q.data; }
  }
  catch (e) { error.value = e.response?.data?.message || 'No fue posible cargar la información'; } finally { loading.value = false; }
}
async function createCategory() { await api.post('/categories', categoryForm); Object.assign(categoryForm, { name: '', description: '' }); notice.value='Categoría creada'; await loadData(); }
async function createProduct() { await api.post('/products', { ...productForm, categoryId: Number(productForm.categoryId) }); Object.assign(productForm, { code:'', name:'', salePrice:0, purchaseCost:0, minStock:0, categoryId:'' }); notice.value='Producto creado'; await loadData(); }
async function createPerson(kind) { await api.post(`/${kind}`, kind === 'customers' ? customerForm : supplierForm); Object.assign(kind === 'customers' ? customerForm : supplierForm, { name: '', document: '', phone: '', address: '' }); notice.value = kind === 'customers' ? 'Cliente creado' : 'Proveedor creado'; await loadData(); }
async function createQuotation() { await api.post('/quotations', { customerId: quotationForm.customerId ? Number(quotationForm.customerId) : undefined, items: [{ productId: Number(quotationForm.productId), quantity: Number(quotationForm.quantity), unitPrice: Number(quotationForm.unitPrice) }] }); Object.assign(quotationForm, { customerId: '', productId: '', quantity: 1, unitPrice: 0 }); notice.value = 'Cotización creada'; await loadData(); }
function startQuotationEdit(q) { quotationEditing.value = q; Object.assign(quotationForm, { customerId: q.customerId ? String(q.customerId) : '', productId: q.items?.[0]?.productId ? String(q.items[0].productId) : '', quantity: Number(q.items?.[0]?.quantity || 1), unitPrice: Number(q.items?.[0]?.unitPrice || 0) }); }
function cancelQuotationEdit() { quotationEditing.value = null; Object.assign(quotationForm, { customerId: '', productId: '', quantity: 1, unitPrice: 0 }); }
async function saveQuotationEdit() { await api.put(`/quotations/${quotationEditing.value.id}`, { customerId: quotationForm.customerId ? Number(quotationForm.customerId) : undefined, items: [{ productId: Number(quotationForm.productId), quantity: Number(quotationForm.quantity), unitPrice: Number(quotationForm.unitPrice) }] }); notice.value = 'Cotización actualizada'; cancelQuotationEdit(); await loadData(); }
async function cancelQuotation(id) { if (!confirm('¿Anular esta cotización?')) return; await api.post(`/quotations/${id}/cancel`); notice.value = 'Cotización anulada'; await loadData(); }
async function createUser() { await api.post('/users', userForm); Object.assign(userForm, { name: '', username: '', password: '', role: 'OPERATOR' }); notice.value = 'Usuario creado'; await loadData(); }
function startUserEdit(row) { userEditing.value = row; Object.assign(userEditForm, { name: row.name, username: row.username, password: '', role: row.role, active: row.active }); }
function cancelUserEdit() { userEditing.value = null; Object.assign(userEditForm, { name: '', username: '', password: '', role: 'OPERATOR', active: true }); }
async function saveUserEdit() { await api.put(`/users/${userEditing.value.id}`, { ...userEditForm, password: userEditForm.password || undefined }); notice.value = 'Usuario actualizado'; cancelUserEdit(); await loadData(); }
async function deactivateUser(id) { if (!confirm('¿Desactivar este usuario?')) return; await api.delete(`/users/${id}`); notice.value = 'Usuario desactivado'; await loadData(); }
async function saveSetting() { await api.post('/settings', settingForm); Object.assign(settingForm, { key: '', value: '' }); notice.value = 'Configuración guardada'; await loadData(); }
async function createLot() { await api.post('/inventory/lots', { productId: Number(lotForm.productId), code: lotForm.code, expiryDate: lotForm.expiryDate || undefined, quantity: Number(lotForm.quantity) }); Object.assign(lotForm, { productId: '', code: '', expiryDate: '', quantity: 0 }); notice.value = 'Lote creado'; await loadData(); }
function startLotEdit(lot) { lotEditing.value = lot; Object.assign(lotForm, { productId: String(lot.productId), code: lot.code, expiryDate: lot.expiryDate ? new Date(lot.expiryDate).toISOString().slice(0, 10) : '', quantity: Number(lot.quantity) }); }
function cancelLotEdit() { lotEditing.value = null; Object.assign(lotForm, { productId: '', code: '', expiryDate: '', quantity: 0 }); }
async function saveLot() { await api.put(`/inventory/lots/${lotEditing.value.id}`, { productId: Number(lotForm.productId), code: lotForm.code, expiryDate: lotForm.expiryDate || undefined, quantity: Number(lotForm.quantity) }); notice.value = 'Lote actualizado'; cancelLotEdit(); await loadData(); }
async function deactivateLot(id) { if (!confirm('¿Desactivar este lote? Se conservarán sus movimientos.')) return; await api.delete(`/inventory/lots/${id}`); notice.value = 'Lote desactivado'; await loadData(); }
async function adjustInventory() { try { await api.post('/inventory/adjust', { productId: Number(adjustmentForm.productId), lotId: adjustmentForm.lotId ? Number(adjustmentForm.lotId) : undefined, type: adjustmentForm.type, quantity: Number(adjustmentForm.quantity), reference: adjustmentForm.reference || undefined }); Object.assign(adjustmentForm, { productId: '', lotId: '', type: 'ADJUSTMENT', quantity: 0, reference: '' }); notice.value = 'Movimiento registrado'; await loadData(); } catch (e) { error.value = e.response?.data?.message || 'No fue posible registrar el movimiento'; } }
async function createExpense() { await api.post('/expenses', { ...expenseForm, amount: Number(expenseForm.amount), expenseDate: expenseForm.expenseDate || undefined }); Object.assign(expenseForm, { description: '', category: '', amount: 0, expenseDate: '' }); notice.value = 'Gasto registrado'; await loadData(); }
async function loadCustomerHistory() { customerHistory.value = (await api.get(`/customer-history/${historyForm.customerId}`)).data; }
async function createAccountPayment() { await api.post('/customer-history/payments', { customerId: Number(historyForm.customerId), amount: Number(historyForm.amount), type: historyForm.type, reference: historyForm.reference || undefined }); notice.value = 'Cobro registrado'; historyForm.amount = 0; historyForm.reference = ''; await loadCustomerHistory(); }
async function changePaymentStatus(id, status) { await api.post(`/payments/${id}/status`, { status }); notice.value = status === 'CANCELLED' ? 'Pago cancelado' : 'Pago activado'; await loadData(); }
async function changeInstallmentStatus(id, status) { await api.post(`/installments/${id}/status`, { status }); notice.value = status === 'PAID' ? 'Cuota marcada como pagada' : 'Estado de cuota actualizado'; await loadData(); }
async function cancelDocument(kind, id) { if (!confirm('¿Confirmar anulación?')) return; await api.post(`/${kind}/${id}/cancel`); notice.value = 'Documento anulado'; await loadData(); }
async function convertQuotation(id) { if (!confirm('¿Convertir esta cotización en venta?')) return; await api.post(`/quotations/${id}/convert`); notice.value = 'Cotización convertida en venta'; await loadData(); }
function addOperationItem() { operation.items.push({ productId: '', quantity: 1, price: 0 }); }
function removeOperationItem(index) { if (operation.items.length > 1) operation.items.splice(index, 1); }
async function createOperation(kind) { try { const body={items:operation.items.map((item)=>({ productId:Number(item.productId), quantity:Number(item.quantity), [kind==='sale'?'unitPrice':'unitCost']:Number(item.price) }))}; if(operation.personId) body[kind==='sale'?'customerId':'supplierId']=Number(operation.personId); await api.post(kind==='sale'?'/sales':'/purchases',body); notice.value=kind==='sale'?'Venta registrada correctamente':'Compra registrada correctamente'; operation.personId=''; operation.items.splice(0, operation.items.length, { productId:'', quantity:1, price:0 }); await loadData(); } catch (e) { error.value = e.response?.data?.message || `No fue posible registrar la ${kind === 'sale' ? 'venta' : 'compra'}`; } }
async function downloadReport(extension) { const response = await api.get(`/reports/sales.${extension}`, { responseType: 'blob' }); const url = URL.createObjectURL(response.data); const link = document.createElement('a'); link.href = url; link.download = `ventas.${extension}`; link.click(); URL.revokeObjectURL(url); }
async function downloadReceipt(kind, id) { const response = await api.get(`/documents/${kind}/${id}/receipt.pdf`, { responseType: 'blob' }); const url = URL.createObjectURL(response.data); const link = document.createElement('a'); link.href = url; link.download = `recibo-${kind.slice(0, -1)}.pdf`; link.click(); URL.revokeObjectURL(url); }
function openReceipt(kind, id) { const source = kind === 'sales' ? sales.value : purchases.value; receiptPreview.value = { kind, document: source.find(doc => doc.id === id) }; }
function closeReceipt() { receiptPreview.value = null; }
function startEdit(doc, kind) { editing.value = { kind, id: doc.id, number: doc.number }; editForm.personId = String(kind === 'sales' ? (doc.customerId || '') : (doc.supplierId || '')); editForm.items.splice(0, editForm.items.length, ...(doc.items || []).map(item => ({ productId: String(item.productId), quantity: Number(item.quantity), price: Number(kind === 'sales' ? item.unitPrice : item.unitCost) }))); }
function cancelEdit() { editing.value = null; editForm.personId = ''; editForm.items.splice(0); }
function startCatalogEdit(row, kind) { catalogEditing.value = { kind, id: row.id }; Object.assign(catalogEditForm, { name: row.name || '', description: row.description || '', code: row.code || '', salePrice: Number(row.salePrice || 0), purchaseCost: Number(row.purchaseCost || 0), minStock: Number(row.minStock || 0), categoryId: row.categoryId || row.category?.id || '', document: row.document || '', phone: row.phone || '', address: row.address || '' }); }
function cancelCatalogEdit() { catalogEditing.value = null; Object.assign(catalogEditForm, { name: '', description: '', code: '', salePrice: 0, purchaseCost: 0, minStock: 0, categoryId: '', document: '', phone: '', address: '' }); }
async function saveCatalogEdit() { const { kind, id } = catalogEditing.value; const body = kind === 'categories' ? { name: catalogEditForm.name, description: catalogEditForm.description || undefined } : kind === 'products' ? { code: catalogEditForm.code, name: catalogEditForm.name, salePrice: Number(catalogEditForm.salePrice), purchaseCost: Number(catalogEditForm.purchaseCost), minStock: Number(catalogEditForm.minStock), categoryId: Number(catalogEditForm.categoryId) } : { name: catalogEditForm.name, document: catalogEditForm.document || undefined, phone: catalogEditForm.phone || undefined, address: catalogEditForm.address || undefined }; await api.put(`/${kind}/${id}`, body); notice.value = 'Registro actualizado'; cancelCatalogEdit(); await loadData(); }
async function deactivateCatalog(kind, id) { if (!confirm('¿Desea desactivar este registro? Se conservarán sus operaciones históricas.')) return; await api.delete(`/${kind}/${id}`); notice.value = 'Registro desactivado'; await loadData(); }
async function saveEdit() { const kind = editing.value.kind; const body = { items: editForm.items.map(item => ({ productId: Number(item.productId), quantity: Number(item.quantity), [kind === 'sales' ? 'unitPrice' : 'unitCost']: Number(item.price) })) }; if (editForm.personId) body[kind === 'sales' ? 'customerId' : 'supplierId'] = Number(editForm.personId); await api.put(`/${kind}/${editing.value.id}`, body); notice.value = `${kind === 'sales' ? 'Venta' : 'Compra'} actualizada`; cancelEdit(); await loadData(); }
async function setupTwoFactor() { twoFactor.value = (await api.post('/auth/2fa/setup')).data; }
async function confirmTwoFactor() { await api.post('/auth/2fa/confirm', { token: twoFactorToken.value }); notice.value = '2FA confirmado correctamente'; twoFactorToken.value = ''; }
async function createPayment() { const path = paymentForm.documentType === 'sale' ? 'sales' : 'purchases'; await api.post(`/payments/${path}/${paymentForm.documentId}`, { amount: Number(paymentForm.amount), type: paymentForm.type, reference: paymentForm.reference || undefined }); notice.value = 'Pago registrado'; Object.assign(paymentForm, { documentId: '', amount: 0, reference: '' }); await loadData(); }
async function createInstallment() { const path = installmentForm.documentType === 'sale' ? 'sales' : 'purchases'; await api.post(`/installments/${path}/${installmentForm.documentId}`, { amount: Number(installmentForm.amount), dueDate: installmentForm.dueDate }); notice.value = 'Cuota registrada'; Object.assign(installmentForm, { documentId: '', amount: 0, dueDate: '' }); await loadData(); }
onMounted(loadData);
</script>

<template>
  <div v-if="!isLogged" class="login-shell theme-glass"><section class="glass-login"><img class="login-logo left" src="/assets/logos/san-benjamin.png" alt="San Benjamin"><img class="login-logo right" src="/assets/logos/supra-medic.png" alt="Supra Medic"><div class="glass-form"><h1>Bienvenido</h1><p>Acceso privado al sistema.</p><div class="theme-switch-row"><span>Modo oscuro</span><label class="theme-toggle"><input type="checkbox" :checked="isDark" @change="toggleTheme"><span class="theme-toggle-track"><span class="theme-toggle-knob"></span></span></label></div><div class="exchange-box"><span>Tipo de cambio del día</span><strong>Bs {{exchangeRate.toFixed(2)}}</strong></div><form @submit.prevent="login"><div class="field"><label>Usuario</label><input v-model="loginForm.username" autocomplete="username" required autofocus></div><div class="field"><label>Contraseña</label><input v-model="loginForm.password" type="password" autocomplete="current-password" required></div><div v-if="loginError" class="errors">{{ loginError }}</div><button>Entrar</button></form><small class="login-note">San Benjamin · Supra Medic</small></div></section></div>
  <div v-else class="theme-glass app-shell"><nav class="glass-dock"><a :class="{active:section==='dashboard'}" @click="select('dashboard')">Dashboard</a><div class="dock-group"><button class="dock-trigger">Operación</button><div class="dock-menu"><a @click="select('sales')">Ventas</a><a @click="select('purchases')">Compras</a><a @click="select('quotations')">Cotizaciones</a></div></div><div class="dock-group"><button class="dock-trigger">Inventario</button><div class="dock-menu"><a @click="select('inventory')">Inventario</a><a @click="select('products')">Productos</a><a @click="select('categories')">Categorías</a><a @click="select('movements')">Kardex</a></div></div><div class="dock-group"><button class="dock-trigger">Reportes</button><div class="dock-menu"><a @click="select('reports')">Ventas</a><a @click="select('reports')">Notas / Facturas</a><a @click="select('reports')">Balance mensual</a></div></div><div class="dock-group"><button class="dock-trigger">Administración</button><div class="dock-menu"><a @click="select('customers')">Clientes</a><a @click="select('suppliers')">Proveedores</a><a @click="select('settings')">Configuración</a><a @click="select('users')">Usuarios</a><a @click="select('security')">Seguridad</a><a @click="select('audit')">Auditoría</a></div></div><button @click="logout">Cerrar sesión</button></nav>
    <main class="content"><div class="top"><div><h1>{{ title }}</h1></div><div v-if="section==='dashboard'" class="top-actions"><label class="commercial-select"><span>Nombre comercial</span><img :src="commercialName==='Supra Medic'?'/assets/logos/supra-medic.png':'/assets/logos/san-benjamin.png'" :alt="commercialName"><strong>{{commercialName}}</strong><small>NIT: {{commercialNit}}</small><select v-model="commercialName" @change="changeCommercial"><option>San Benjamin</option><option>Supra Medic</option></select></label><div class="commercial-select"><span>Tipo de cambio del día</span><strong>Bs {{exchangeRate.toFixed(2)}}</strong></div><label class="commercial-select theme-dashboard-switch"><span>Modo oscuro</span><input type="checkbox" :checked="isDark" @change="toggleTheme"><span class="theme-toggle-track"><span class="theme-toggle-knob"></span></span></label><span class="user-pill"><i class="bi bi-person-circle"></i> {{ user?.name }}</span><button class="btn secondary top-action" @click="commercialConfirmed=false">Cambiar</button><button class="btn top-action" @click="select('sale')">Nueva venta</button><button class="btn top-action" @click="select('purchase')">Nueva compra</button></div><div v-else class="actions module-top-actions"><button class="btn secondary" @click="select('dashboard')">Dashboard</button><button v-if="section==='sales'" class="btn" @click="select('sale')">Nueva venta</button><button v-if="section==='purchases'" class="btn" @click="select('purchase')">Nueva compra</button><button v-if="section==='inventory'" class="btn" @click="select('products')">Crear producto</button><button v-if="section==='inventory'" class="btn secondary" @click="select('movements')">Ver movimientos</button><button v-if="section==='inventory'" class="btn secondary" @click="select('lots')">Lotes y vencimientos</button></div></div><div v-if="notice" class="notice">{{ notice }}</div><div v-if="error" class="errors">{{ error }}</div><div v-if="loading" class="notice">Cargando…</div>
      <div v-if="editing" class="edit-overlay"><section class="panel edit-dialog"><div class="section-head"><div><p class="eyebrow">Edición segura</p><h2>{{editing.kind==='sales'?'Editar venta':'Editar compra'}} {{editing.number}}</h2></div><button class="btn secondary" type="button" @click="cancelEdit">Cerrar</button></div><form class="form-grid" @submit.prevent="saveEdit"><select v-model="editForm.personId"><option value="">General</option><option v-for="r in (editing.kind==='sales'?customers:suppliers)" :value="r.id" :key="r.id">{{r.name}}</option></select><span></span><span></span><div v-for="(item,index) in editForm.items" :key="index" class="operation-row"><select v-model="item.productId" required><option value="">Producto</option><option v-for="p in products" :value="p.id" :key="p.id">{{p.code}} · {{p.name}}</option></select><input v-model.number="item.quantity" type="number" min="0.001" step="0.001" required><input v-model.number="item.price" type="number" min="0" step="0.01" required></div><div class="actions"><button class="btn" type="submit">Guardar cambios</button><button class="btn secondary" type="button" @click="cancelEdit">Cancelar</button></div></form></section></div>
      <div v-if="catalogEditing" class="edit-overlay"><section class="panel edit-dialog catalog-dialog"><div class="section-head"><div><p class="eyebrow">Edición de catálogo</p><h2>Editar {{catalogEditing.kind==='categories'?'categoría':catalogEditing.kind==='products'?'producto':catalogEditing.kind==='customers'?'cliente':'proveedor'}}</h2></div><button class="btn secondary" type="button" @click="cancelCatalogEdit">Cerrar</button></div><form class="form-grid" @submit.prevent="saveCatalogEdit"><template v-if="catalogEditing.kind==='categories'"><input v-model="catalogEditForm.name" placeholder="Nombre" required><input v-model="catalogEditForm.description" placeholder="Descripción"><span></span></template><template v-else-if="catalogEditing.kind==='products'"><input v-model="catalogEditForm.code" placeholder="Código" required><input v-model="catalogEditForm.name" placeholder="Nombre" required><select v-model="catalogEditForm.categoryId" required><option value="">Categoría</option><option v-for="c in categories" :value="c.id" :key="c.id">{{c.name}}</option></select><input v-model.number="catalogEditForm.purchaseCost" type="number" min="0" step="0.01" placeholder="Costo"><input v-model.number="catalogEditForm.salePrice" type="number" min="0" step="0.01" placeholder="Precio venta"><input v-model.number="catalogEditForm.minStock" type="number" min="0" step="0.001" placeholder="Stock mínimo"></template><template v-else><input v-model="catalogEditForm.name" placeholder="Nombre" required><input v-model="catalogEditForm.document" placeholder="Documento"><input v-model="catalogEditForm.phone" placeholder="Teléfono"><input v-model="catalogEditForm.address" placeholder="Dirección"><span></span></template><div class="actions"><button class="btn" type="submit">Guardar cambios</button><button class="btn secondary" type="button" @click="cancelCatalogEdit">Cancelar</button></div></form></section></div>
      <div v-if="userEditing" class="edit-overlay"><section class="panel edit-dialog"><div class="section-head"><div><p class="eyebrow">Administración</p><h2>Editar usuario</h2></div><button class="btn secondary" type="button" @click="cancelUserEdit">Cerrar</button></div><form class="form-grid" @submit.prevent="saveUserEdit"><input v-model="userEditForm.name" placeholder="Nombre" required><input v-model="userEditForm.username" placeholder="Usuario" required><input v-model="userEditForm.password" type="password" placeholder="Nueva contraseña (opcional)"><select v-model="userEditForm.role"><option value="OPERATOR">Operador</option><option value="ADMIN">Administrador</option></select><label class="theme-switch-row"><span>Usuario activo</span><input v-model="userEditForm.active" type="checkbox"></label><div class="actions"><button class="btn" type="submit">Guardar cambios</button><button class="btn secondary" type="button" @click="cancelUserEdit">Cancelar</button></div></form></section></div>
      <div v-if="receiptPreview" class="edit-overlay"><section class="panel receipt-dialog"><div class="section-head"><div><p class="eyebrow">Vista previa</p><h2>Recibo del documento</h2></div><button class="btn secondary" type="button" @click="closeReceipt">Cerrar</button></div><article class="receipt-sheet"><header class="receipt-header"><img :src="commercialName==='Supra Medic'?'/assets/logos/supra-medic.png':'/assets/logos/san-benjamin.png'" :alt="commercialName"><div><strong>{{commercialName}}</strong><span>{{receiptPreview.kind==='sales'?'RECIBO DE VENTA':'RECIBO DE COMPRA'}}</span></div></header><div class="receipt-meta"><span>Número: <strong>{{receiptPreview.document?.number}}</strong></span><span>Fecha: {{new Date(receiptPreview.document?.createdAt).toLocaleString('es-BO')}}</span><span>Estado: <strong>{{receiptPreview.document?.status}}</strong></span></div><table><thead><tr><th>Producto</th><th>Cantidad</th><th>Precio</th><th>Subtotal</th></tr></thead><tbody><tr v-for="item in (receiptPreview.document?.items||[])" :key="item.id"><td>{{item.product?.name}}</td><td>{{item.quantity}}</td><td>{{Number(receiptPreview.kind==='sales'?item.unitPrice:item.unitCost).toFixed(2)}}</td><td>{{Number(item.subtotal).toFixed(2)}}</td></tr></tbody></table><div class="receipt-total">Total: Bs {{Number(receiptPreview.document?.total||0).toFixed(2)}}</div><small class="receipt-footer">Documento generado por Sistema San Benjamin-SupraMedic</small></article></section></div>
      <div v-if="activeDashboardAlert && section==='dashboard' && dashboardAlertIndex < dashboardAlerts.length" class="edit-overlay dashboard-alert-overlay"><section class="panel alert-dialog"><p class="eyebrow">Aviso del sistema</p><h2>{{activeDashboardAlert.title}}</h2><p>{{activeDashboardAlert.detail}}.</p><div class="alert-item"><strong><span>Registros detectados</span><span>{{activeDashboardAlert.count}}</span></strong><small>Revise el módulo correspondiente antes de continuar.</small></div><div class="actions"><button class="btn" @click="closeDashboardAlert">Entendido</button><button class="btn secondary" @click="closeDashboardAlert; select(activeDashboardAlert.type==='stock'?'inventory':activeDashboardAlert.type==='expiry'?'lots':'installments')">Revisar módulo</button></div></section></div>
      <section v-if="section==='dashboard'" class="dashboard-view"><div class="cards"><div class="metric"><span>Ventas del día</span><strong>{{ summary?.sales?.count ?? 0 }}</strong></div><div class="metric"><span>Total vendido</span><strong>Bs {{Number(summary?.sales?.total||0).toFixed(2)}}</strong></div><div class="metric"><span>Stock bajo</span><strong>{{ dashboardAlerts.find(a=>a.type==='stock')?.count || 0 }}</strong></div><div class="metric"><span>Documentos con stock pendiente</span><strong>{{ pendingStockDocuments }}</strong></div><div class="metric"><span>Movimientos</span><strong>{{ movements.length }}</strong></div><div class="metric"><span>Cuentas por cobrar</span><strong>Bs {{ receivableAmount.toFixed(2) }}</strong></div></div><div class="dashboard-grid"><section class="panel monthly-summary"><div class="monthly-summary-head"><div><span class="eyebrow">Resumen financiero del mes · {{commercialName}}</span><h2>Movimiento mensual</h2><p class="muted">Ventas, compras y gastos operativos del período actual.</p></div><span class="monthly-status" :class="Number(monthly?.result||0)>=0?'is-positive':'is-negative'"><strong>{{Number(monthly?.result||0)>=0?'Ganancia':'Pérdida'}}</strong><small>Ventas - compras - gastos</small></span></div><div class="monthly-kpis"><div class="monthly-kpi sales"><span>Ventas</span><strong>Bs {{Number(monthly?.sales||0).toFixed(2)}}</strong><small>Ingresos del período</small></div><div class="monthly-kpi purchases"><span>Compras</span><strong>Bs {{Number(monthly?.purchases||0).toFixed(2)}}</strong><small>Entradas de inventario</small></div><div class="monthly-kpi purchases"><span>Gastos operativos</span><strong>Bs {{Number(monthly?.expenses||0).toFixed(2)}}</strong><small>Gastos del período</small></div><div class="monthly-kpi result" :class="Number(monthly?.result||0)>=0?'is-positive':'is-negative'"><span>Resultado comercial</span><strong>Bs {{Number(monthly?.result||0).toFixed(2)}}</strong><small>Resultado neto</small></div></div><div class="monthly-bar"><span class="monthly-bar-sales" :style="{width: `${Math.min(100, Number(monthly?.sales||0) / Math.max(Number(monthly?.sales||0)+Number(monthly?.purchases||0)+Number(monthly?.expenses||0),1)*100)}%`}"></span><span class="monthly-bar-purchases" :style="{width: `${Math.min(100, Number(monthly?.purchases||0) / Math.max(Number(monthly?.sales||0)+Number(monthly?.purchases||0)+Number(monthly?.expenses||0),1)*100)}%`}"></span></div></section><section class="panel"><h2>Movimientos de inventario</h2><div class="timeline"><div v-for="m in movements.slice(0,4)" :key="m.id" class="timeline-row"><span>{{new Date(m.createdAt).toLocaleTimeString('es-BO',{hour:'2-digit',minute:'2-digit'})}}</span><div><b>{{m.type}}</b><br><span class="muted">{{m.product?.name}} · {{m.quantity}}</span></div><span class="pill">Stock</span></div><div v-if="!movements.length" class="compact-item"><b>Sin movimientos recientes</b><span class="pill">OK</span></div></div></section></div><div class="dashboard-bottom"><section class="panel"><h2>Stock bajo</h2><div class="compact-list"><div v-for="product in inventory.filter(p=>Number(p.stock)<=Number(p.minStock)).slice(0,5)" :key="product.id" class="compact-item"><div><b>{{product.code}} - {{product.name}}</b><small>{{product.category?.name||'Sin categoría'}} · Mínimo {{Number(product.minStock||0).toFixed(2)}}</small></div><span class="pill">{{Number(product.stock||0).toFixed(2)}}</span></div><div v-if="!inventory.some(p=>Number(p.stock)<=Number(p.minStock))" class="compact-item"><b>Sin productos en alerta</b><span class="pill">OK</span></div></div></section><section class="panel"><div class="top"><h2>Faltantes de stock</h2><button class="btn secondary" @click="select('inventory')">Regularizar faltantes</button></div><div class="compact-list"><div class="compact-item"><div><b>Sin faltantes pendientes</b><small>No existen productos ni documentos con stock faltante.</small></div><span class="pill">OK</span></div></div></section><section class="panel"><h2>Alertas de datos</h2><div class="compact-list"><div v-for="alert in dashboardAlerts" :key="alert.type" class="alert-item"><strong><span>{{alert.title}}</span><span>{{alert.count}}</span></strong><small>{{alert.detail}}</small></div><div v-if="!dashboardAlerts.length" class="compact-item"><div><b>Sin alertas activas</b><small>El inventario y las cuentas están dentro de los parámetros.</small></div><span class="pill">OK</span></div></div></section><section class="panel"><h2>Últimas operaciones</h2><div class="compact-list"><div v-for="sale in sales.slice(0,5)" :key="sale.id" class="compact-item"><div><b>Venta {{sale.number}}</b><small>{{new Date(sale.createdAt).toLocaleDateString('es-BO')}} · {{commercialName}}</small></div><span class="pill">Bs {{Number(sale.total).toFixed(2)}}</span></div><div v-if="!sales.length" class="compact-item"><b>Sin operaciones recientes</b><span class="pill">Nuevo</span></div></div></section><section class="panel"><h2>Vencimientos y cuotas</h2><div class="compact-list"><div v-for="alert in dashboardAlerts.filter(a=>a.type!=='stock')" :key="alert.type" class="alert-item"><strong><span>{{alert.title}}</span><span>{{alert.count}}</span></strong><small>{{alert.detail}}</small></div><div v-if="!dashboardAlerts.some(a=>a.type!=='stock')" class="compact-item"><b>Sin vencimientos cercanos</b><span class="pill">OK</span></div></div></section><section class="panel"><div class="top"><h2>Cuentas y cuotas por cobrar</h2><button class="btn secondary" @click="select('history')">Ver cartera</button></div><div class="compact-list"><div class="compact-item"><div><b>{{ installments.filter(i=>i.status==='PENDING').length }} documentos por cobrar</b><small>Incluye facturas, notas y cuotas con saldo pendiente.</small></div><span class="pill">Bs {{ receivableAmount.toFixed(2) }}</span></div><div v-if="!installments.some(i=>i.status==='PENDING')" class="compact-item"><div><b>Sin cuotas con atraso</b><small>La alerta aparece después del vencimiento.</small></div><span class="pill">OK</span></div></div></section></div></section>
      <section v-else-if="section==='reports'" class="reports-view"><div class="panel"><p class="eyebrow">Centro de reportes · {{commercialName}}</p><h2>Reportes del negocio</h2><p class="muted">Información operativa y financiera cargada desde PostgreSQL.</p><div class="report-tabs"><button :class="{active:reportTab==='summary'}" @click="reportTab='summary'">Balance</button><button :class="{active:reportTab==='sales'}" @click="reportTab='sales'">Ventas</button><button :class="{active:reportTab==='purchases'}" @click="reportTab='purchases'">Compras</button><button :class="{active:reportTab==='inventory'}" @click="reportTab='inventory'">Inventario</button><button :class="{active:reportTab==='movements'}" @click="reportTab='movements'">Kardex</button><button :class="{active:reportTab==='expenses'}" @click="reportTab='expenses'">Gastos</button></div><div v-if="reportTab==='summary'" class="grid cols-4"><div class="metric"><span>Ventas del período</span><strong>{{Number(monthly?.sales||0).toFixed(2)}} Bs</strong></div><div class="metric"><span>Compras del período</span><strong>{{Number(monthly?.purchases||0).toFixed(2)}} Bs</strong></div><div class="metric"><span>Gastos operativos</span><strong>{{Number(monthly?.expenses||0).toFixed(2)}} Bs</strong></div><div class="metric"><span>Balance</span><strong>{{Number(monthly?.result||0).toFixed(2)}} Bs</strong></div></div><div v-else-if="reportTab==='sales'"><div class="actions"><button class="btn" @click="downloadReport('pdf')">Descargar PDF</button><button class="btn secondary" @click="downloadReport('xlsx')">Descargar Excel</button></div><table><thead><tr><th>Número</th><th>Cliente</th><th>Fecha</th><th>Total</th><th>Estado</th></tr></thead><tbody><tr v-for="sale in sales" :key="sale.id"><td>{{sale.number}}</td><td>{{sale.customer?.name||'General'}}</td><td>{{new Date(sale.createdAt).toLocaleDateString('es-BO')}}</td><td>Bs {{Number(sale.total).toFixed(2)}}</td><td>{{sale.status}}</td></tr></tbody></table></div><div v-else-if="reportTab==='purchases'"><table><thead><tr><th>Número</th><th>Proveedor</th><th>Fecha</th><th>Total</th><th>Estado</th></tr></thead><tbody><tr v-for="purchase in purchases" :key="purchase.id"><td>{{purchase.number}}</td><td>{{purchase.supplier?.name||'General'}}</td><td>{{new Date(purchase.createdAt).toLocaleDateString('es-BO')}}</td><td>Bs {{Number(purchase.total).toFixed(2)}}</td><td>{{purchase.status}}</td></tr></tbody></table></div><div v-else-if="reportTab==='inventory'"><table><thead><tr><th>Código</th><th>Producto</th><th>Categoría</th><th>Stock</th><th>Mínimo</th><th>Estado</th></tr></thead><tbody><tr v-for="product in inventory" :key="product.id"><td>{{product.code}}</td><td>{{product.name}}</td><td>{{product.category?.name||'—'}}</td><td>{{product.stock}}</td><td>{{product.minStock}}</td><td>{{Number(product.stock)<=Number(product.minStock)?'Stock bajo':'Disponible'}}</td></tr></tbody></table></div><div v-else-if="reportTab==='movements'"><table><thead><tr><th>Fecha</th><th>Producto</th><th>Lote</th><th>Tipo</th><th>Cantidad</th><th>Referencia</th></tr></thead><tbody><tr v-for="movement in movements" :key="movement.id"><td>{{new Date(movement.createdAt).toLocaleString('es-BO')}}</td><td>{{movement.product?.name}}</td><td>{{movement.lot?.code||'—'}}</td><td>{{movement.type}}</td><td>{{movement.quantity}}</td><td>{{movement.reference||'—'}}</td></tr></tbody></table></div><div v-else><table><thead><tr><th>Descripción</th><th>Categoría</th><th>Fecha</th><th>Importe</th></tr></thead><tbody><tr v-for="expense in expenses" :key="expense.id"><td>{{expense.description}}</td><td>{{expense.category||'—'}}</td><td>{{new Date(expense.expenseDate).toLocaleDateString('es-BO')}}</td><td>Bs {{Number(expense.amount).toFixed(2)}}</td></tr></tbody></table></div></div></section>
      <section v-else-if="section==='categories'" class="panel"><div class="section-head"><h2>Categorías</h2><form class="inline-form" @submit.prevent="createCategory"><input v-model="categoryForm.name" placeholder="Nombre" required><input v-model="categoryForm.description" placeholder="Descripción"><button class="btn">Guardar</button></form></div><table><thead><tr><th>Nombre</th><th>Descripción</th><th>Productos</th><th>Acciones</th></tr></thead><tbody><tr v-for="r in categories" :key="r.id"><td>{{r.name}}</td><td>{{r.description||'—'}}</td><td>{{r._count?.products??0}}</td><td class="row-actions"><button class="btn secondary" @click="startCatalogEdit(r,'categories')">Editar</button><button class="btn danger" @click="deactivateCatalog('categories',r.id)">Desactivar</button></td></tr></tbody></table></section>
      <section v-else-if="section==='products'" class="panel"><div class="section-head"><h2>Productos</h2></div><form class="form-grid" @submit.prevent="createProduct"><input v-model="productForm.code" placeholder="Código" required><input v-model="productForm.name" placeholder="Nombre" required><select v-model="productForm.categoryId" required><option value="">Categoría</option><option v-for="c in categories" :value="c.id" :key="c.id">{{c.name}}</option></select><input v-model.number="productForm.purchaseCost" type="number" min="0" placeholder="Costo"><input v-model.number="productForm.salePrice" type="number" min="0" placeholder="Precio venta"><button class="btn">Guardar producto</button></form><table><thead><tr><th>Código</th><th>Producto</th><th>Categoría</th><th>Precio</th><th>Stock</th><th>Acciones</th></tr></thead><tbody><tr v-for="p in products" :key="p.id"><td>{{p.code}}</td><td>{{p.name}}</td><td>{{p.category?.name}}</td><td>{{Number(p.salePrice).toFixed(2)}}</td><td><span class="pill">{{p.stock}}</span></td><td class="row-actions"><button class="btn secondary" @click="startCatalogEdit(p,'products')">Editar</button><button class="btn danger" @click="deactivateCatalog('products',p.id)">Desactivar</button></td></tr></tbody></table></section>
      <section v-else-if="section==='customers'||section==='suppliers'" class="panel"><h2>{{section==='customers'?'Clientes':'Proveedores'}}</h2><form class="form-grid" @submit.prevent="createPerson(section)"><input v-model="(section==='customers'?customerForm:supplierForm).name" placeholder="Nombre" required><input v-model="(section==='customers'?customerForm:supplierForm).document" placeholder="Documento"><input v-model="(section==='customers'?customerForm:supplierForm).phone" placeholder="Teléfono"><input v-model="(section==='customers'?customerForm:supplierForm).address" placeholder="Dirección"><button class="btn">Guardar {{section==='customers'?'cliente':'proveedor'}}</button></form><table><thead><tr><th>Nombre</th><th>Documento</th><th>Teléfono</th><th>Acciones</th></tr></thead><tbody><tr v-for="r in (section==='customers'?customers:suppliers)" :key="r.id"><td>{{r.name}}</td><td>{{r.document||'—'}}</td><td>{{r.phone||'—'}}</td><td class="row-actions"><button class="btn secondary" @click="startCatalogEdit(r,section)">Editar</button><button class="btn danger" @click="deactivateCatalog(section,r.id)">Desactivar</button></td></tr></tbody></table></section>
      <section v-else-if="section==='quotations'" class="panel quotation-module"><div class="card quotation-editor-card"><div class="section-head"><div><p class="eyebrow">Operación comercial</p><h2>{{quotationEditing?'Editar cotización':'Registro de cotización'}}</h2><p class="muted">Complete los datos de la cotización y revise los totales antes de guardar.</p></div><span class="pill">Tipo de cambio Bs {{exchangeRate.toFixed(2)}}</span></div><form @submit.prevent="quotationEditing?saveQuotationEdit():createQuotation"><div class="row quotation-meta"><label class="field"><span>Nombre comercial</span><select v-model="commercialName"><option>San Benjamin</option><option>Supra Medic</option></select></label><label class="field"><span>Cliente</span><select v-model="quotationForm.customerId"><option value="">Sin cliente</option><option v-for="c in customers" :value="c.id" :key="c.id">{{c.name}}</option></select></label><label class="field"><span>Producto</span><select v-model="quotationForm.productId" required @change="quotationForm.unitPrice=Number(selectedQuotationProduct?.salePrice||0)"><option value="">Seleccionar producto</option><option v-for="p in products" :value="p.id" :key="p.id">{{p.code}} · {{p.name}}</option></select></label><label class="field"><span>Cantidad</span><input v-model.number="quotationForm.quantity" type="number" min="0.001" step="0.001" required></label><label class="field"><span>Precio cotizado</span><input v-model.number="quotationForm.unitPrice" type="number" min="0" step="0.01" required></label></div><div class="card quotation-detail-card"><div class="section-head"><h2>Detalle de productos</h2><span class="muted">{{selectedQuotationProduct?.name||'Sin producto seleccionado'}}</span></div><table><thead><tr><th>Código</th><th>Producto</th><th>Existencia</th><th>Cantidad</th><th>Precio</th><th>Total</th></tr></thead><tbody><tr v-if="selectedQuotationProduct"><td>{{selectedQuotationProduct.code}}</td><td>{{selectedQuotationProduct.name}}</td><td>{{selectedQuotationProduct.stock}}</td><td>{{Number(quotationForm.quantity).toFixed(2)}}</td><td>Bs {{Number(quotationForm.unitPrice).toFixed(2)}}</td><td>Bs {{quotationTotal.toFixed(2)}}</td></tr><tr v-else><td colspan="6" class="muted">Seleccione un producto para agregarlo a la cotización.</td></tr></tbody><tfoot><tr><th colspan="5" style="text-align:right">Total cotizado</th><th>Bs {{quotationTotal.toFixed(2)}}</th></tr></tfoot></table></div><label class="field quotation-comment"><span>Comentario</span><textarea placeholder="Observaciones o condiciones de la cotización"></textarea></label><div class="actions"><button class="btn">{{quotationEditing?'Guardar cambios':'Registrar cotización'}}</button><button v-if="quotationEditing" type="button" class="btn secondary" @click="cancelQuotationEdit">Cancelar</button></div></form></div><div class="card quotation-history-card"><div class="top"><div><h2>Historial de cotizaciones</h2><p class="muted">Cotizaciones registradas y su estado actual.</p></div><button class="btn" type="button" @click="cancelQuotationEdit">Nueva cotización</button></div><table><thead><tr><th>No.</th><th>Cliente</th><th>Fecha</th><th>Total</th><th>Estado</th><th>Acciones</th></tr></thead><tbody><tr v-for="q in quotations" :key="q.id"><td>{{q.number}}</td><td>{{q.customer?.name||'Sin cliente'}}</td><td>{{new Date(q.createdAt).toLocaleDateString('es-BO')}}</td><td>Bs {{Number(q.total).toFixed(2)}}</td><td><span class="pill">{{q.status}}</span></td><td class="row-actions"><button v-if="q.status==='DRAFT'" class="btn" @click="convertQuotation(q.id)">Convertir a venta</button><button v-if="q.status==='DRAFT'" class="btn secondary" @click="startQuotationEdit(q)">Editar</button><button v-if="q.status==='DRAFT'" class="btn danger" @click="cancelQuotation(q.id)">Anular</button></td></tr><tr v-if="!quotations.length"><td colspan="6" class="muted">No existen cotizaciones registradas.</td></tr></tbody></table></div></section>
      <section v-else-if="section==='payments'" class="panel"><h2>Pagos</h2><form class="form-grid" @submit.prevent="createPayment"><select v-model="paymentForm.documentType"><option value="sale">Venta</option><option value="purchase">Compra</option></select><select v-model="paymentForm.documentId" required><option value="">Documento</option><option v-for="d in (paymentForm.documentType==='sale'?sales:purchases)" :value="d.id" :key="d.id">{{d.number}} · {{Number(d.total).toFixed(2)}}</option></select><input v-model.number="paymentForm.amount" type="number" min="0.01" step="0.01" placeholder="Monto" required><select v-model="paymentForm.type"><option value="CASH">Efectivo</option><option value="CARD">Tarjeta</option><option value="TRANSFER">Transferencia</option></select><input v-model="paymentForm.reference" placeholder="Referencia"><button class="btn">Registrar pago</button></form><table><thead><tr><th>Monto</th><th>Método</th><th>Estado</th><th>Venta</th><th>Compra</th><th>Acción</th></tr></thead><tbody><tr v-for="p in payments" :key="p.id"><td>{{Number(p.amount).toFixed(2)}}</td><td>{{p.type}}</td><td>{{p.status}}</td><td>{{p.sale?.number||'—'}}</td><td>{{p.purchase?.number||'—'}}</td><td><button v-if="p.status==='ACTIVE'" class="btn danger" @click="changePaymentStatus(p.id,'CANCELLED')">Cancelar</button></td></tr></tbody></table></section>
      <section v-else-if="section==='installments'" class="panel"><h2>Cuotas</h2><form class="form-grid" @submit.prevent="createInstallment"><select v-model="installmentForm.documentType"><option value="sale">Venta</option><option value="purchase">Compra</option></select><select v-model="installmentForm.documentId" required><option value="">Documento</option><option v-for="d in (installmentForm.documentType==='sale'?sales:purchases)" :value="d.id" :key="d.id">{{d.number}} · {{Number(d.total).toFixed(2)}}</option></select><input v-model.number="installmentForm.amount" type="number" min="0.01" step="0.01" placeholder="Monto" required><input v-model="installmentForm.dueDate" type="date" required><button class="btn">Registrar cuota</button></form><table><thead><tr><th>Monto</th><th>Vencimiento</th><th>Estado</th><th>Venta</th><th>Compra</th><th>Acción</th></tr></thead><tbody><tr v-for="q in installments" :key="q.id"><td>{{Number(q.amount).toFixed(2)}}</td><td>{{new Date(q.dueDate).toLocaleDateString('es-BO')}}</td><td><span class="pill">{{q.status}}</span></td><td>{{q.sale?.number||'—'}}</td><td>{{q.purchase?.number||'—'}}</td><td><button v-if="q.status==='PENDING'" class="btn" @click="changeInstallmentStatus(q.id,'PAID')">Marcar pagada</button><button v-if="q.status==='PENDING'" class="btn danger" @click="changeInstallmentStatus(q.id,'CANCELLED')">Cancelar</button></td></tr></tbody></table></section>
      <section v-else-if="section==='sales'||section==='purchases'" class="panel documents-module"><form class="card document-filter-card" @submit.prevent><div class="row"><label class="field"><span>Buscar</span><input v-model="documentFilters.search" :placeholder="section==='sales'?'N.º de venta, factura, NIT o cliente':'N.º de compra, factura, NIT o proveedor'"></label><label class="field"><span>Documento</span><select v-model="documentFilters.documentType"><option value="">Todos</option><option value="INVOICE">Factura</option><option value="DELIVERY_NOTE">Nota de entrega</option></select></label><label class="field"><span>Nombre comercial</span><select v-model="documentFilters.commercial"><option value="">Ambos</option><option>San Benjamin</option><option>Supra Medic</option></select></label><label class="field"><span>Año</span><input v-model.number="documentFilters.year" type="number" min="2000" max="2100"></label></div><button class="btn secondary">Buscar documentos</button></form><div class="card document-table-card"><table><thead><tr><th>No.</th><th>{{section==='sales'?'Orden':'Fecha'}}</th><th>Documento</th><th>Fecha</th><th>Factura</th><th>NIT</th><th>{{section==='sales'?'Cliente':'Proveedor'}}</th><th>Total</th><th>Estado</th><th>Pago</th><th>Registró</th><th>Anuló</th><th>Acciones</th></tr></thead><tbody><tr v-for="doc in (section==='sales'?sales:purchases)" :key="doc.id"><td>{{doc.number}}</td><td>{{section==='sales'?commercialName:new Date(doc.createdAt).toLocaleDateString('es-BO')}}</td><td>Factura</td><td>{{new Date(doc.createdAt).toLocaleDateString('es-BO')}}</td><td>—</td><td>—</td><td>{{section==='sales'?(doc.customer?.name||'Sin cliente'):(doc.supplier?.name||'Sin proveedor')}}</td><td>Bs {{Number(doc.total).toFixed(2)}}</td><td>{{doc.status==='ACTIVE'?'Registrada':doc.status}}</td><td>{{doc.status==='ACTIVE'?'Pendiente':'No aplica'}}</td><td>{{user?.name||'—'}}</td><td>—</td><td class="row-actions"><button class="btn secondary" @click="openReceipt(section==='sales'?'sales':'purchases',doc.id)">Ver</button><button class="btn secondary" @click="openReceipt(section==='sales'?'sales':'purchases',doc.id)">Vista previa</button><button v-if="doc.status==='ACTIVE'" class="btn secondary" @click="startEdit(doc,section)">Editar</button></td></tr><tr v-if="!(section==='sales'?sales:purchases).length"><td colspan="13" class="muted">No existen documentos registrados.</td></tr></tbody></table></div></section>
      <section v-else-if="section==='expenses'" class="panel"><h2>Gastos operativos</h2><form class="form-grid" @submit.prevent="createExpense"><input v-model="expenseForm.description" placeholder="Descripción" required><input v-model="expenseForm.category" placeholder="Categoría"><input v-model.number="expenseForm.amount" type="number" min="0.01" step="0.01" placeholder="Monto" required><input v-model="expenseForm.expenseDate" type="date"><button class="btn">Registrar gasto</button></form><table><thead><tr><th>Descripción</th><th>Categoría</th><th>Monto</th><th>Fecha</th></tr></thead><tbody><tr v-for="expense in expenses" :key="expense.id"><td>{{expense.description}}</td><td>{{expense.category||'—'}}</td><td>{{Number(expense.amount).toFixed(2)}}</td><td>{{new Date(expense.expenseDate).toLocaleDateString('es-BO')}}</td></tr></tbody></table></section>
      <section v-else-if="section==='history'" class="panel"><h2>Historial y cobros de clientes</h2><form class="inline-form" @submit.prevent="loadCustomerHistory"><select v-model="historyForm.customerId" required><option value="">Seleccionar cliente</option><option v-for="c in customers" :value="c.id" :key="c.id">{{c.name}}</option></select><button class="btn">Consultar historial</button></form><div v-if="customerHistory" class="grid cols-4"><div class="metric"><span>Total facturado</span><strong>{{Number(customerHistory.charged).toFixed(2)}}</strong></div><div class="metric"><span>Total pagado</span><strong>{{Number(customerHistory.paid).toFixed(2)}}</strong></div><div class="metric"><span>Saldo pendiente</span><strong>{{Number(customerHistory.balance).toFixed(2)}}</strong></div><div class="panel"><form @submit.prevent="createAccountPayment"><input v-model.number="historyForm.amount" type="number" min="0.01" step="0.01" placeholder="Monto del cobro" required><select v-model="historyForm.type"><option value="CASH">Efectivo</option><option value="CARD">Tarjeta</option><option value="TRANSFER">Transferencia</option></select><input v-model="historyForm.reference" placeholder="Referencia"><button class="btn">Registrar cobro</button></form></div></div><table v-if="customerHistory"><thead><tr><th>Venta</th><th>Total</th><th>Estado</th><th>Fecha</th></tr></thead><tbody><tr v-for="sale in customerHistory.sales" :key="sale.id"><td>{{sale.number}}</td><td>{{Number(sale.total).toFixed(2)}}</td><td>{{sale.status}}</td><td>{{new Date(sale.createdAt).toLocaleDateString('es-BO')}}</td></tr></tbody></table></section>
      <section v-else-if="section==='audit'" class="panel"><div class="section-head"><div><p class="eyebrow">Seguridad y trazabilidad</p><h2>Auditoría</h2></div><input v-model="auditFilter" class="audit-search" placeholder="Buscar acción, entidad o usuario"></div><table><thead><tr><th>Acción</th><th>Entidad</th><th>Detalle</th><th>Usuario</th><th>Fecha</th></tr></thead><tbody><tr v-for="event in filteredAudit" :key="event.id"><td>{{event.action}}</td><td>{{event.entity}}</td><td>{{event.details||'—'}}</td><td>{{event.user?.username||'—'}}</td><td>{{new Date(event.createdAt).toLocaleString('es-BO')}}</td></tr><tr v-if="!filteredAudit.length"><td colspan="5" class="muted">No se encontraron eventos.</td></tr></tbody></table></section>
      <section v-else-if="section==='users'" class="panel"><p class="eyebrow">Administración del sistema</p><h2>Usuarios</h2><form class="form-grid" @submit.prevent="createUser"><input v-model="userForm.name" placeholder="Nombre" required><input v-model="userForm.username" placeholder="Usuario" required><input v-model="userForm.password" type="password" placeholder="Contraseña" required><select v-model="userForm.role"><option value="OPERATOR">Operador</option><option value="ADMIN">Administrador</option></select><button class="btn">Crear usuario</button></form><table><thead><tr><th>Nombre</th><th>Usuario</th><th>Rol</th><th>Activo</th><th>2FA</th><th>Acciones</th></tr></thead><tbody><tr v-for="u in users" :key="u.id"><td>{{u.name}}</td><td>{{u.username}}</td><td>{{u.role}}</td><td><span class="pill" :class="u.active?'ok':'low'">{{u.active?'Sí':'No'}}</span></td><td>{{u.twoFactorEnabled?'Activo':'No'}}</td><td class="row-actions"><button class="btn secondary" @click="startUserEdit(u)">Editar</button><button v-if="u.active" class="btn danger" @click="deactivateUser(u.id)">Desactivar</button></td></tr></tbody></table></section>
      <section v-else-if="section==='settings'" class="panel"><h2>Configuración</h2><form class="inline-form" @submit.prevent="saveSetting"><input v-model="settingForm.key" placeholder="Clave" required><input v-model="settingForm.value" placeholder="Valor" required><button class="btn">Guardar</button></form><table><thead><tr><th>Clave</th><th>Valor</th><th>Actualizado</th></tr></thead><tbody><tr v-for="s in settings" :key="s.id"><td>{{s.key}}</td><td>{{s.value}}</td><td>{{new Date(s.updatedAt).toLocaleString('es-BO')}}</td></tr></tbody></table></section>
      <section v-else-if="section==='security'" class="panel"><p class="eyebrow">Autenticación reforzada</p><h2>Google Authenticator / TOTP</h2><p class="muted">Genera una configuración para vincular la cuenta del usuario a una aplicación autenticadora.</p><button class="btn" @click="setupTwoFactor">Generar configuración 2FA</button><div v-if="twoFactor" class="notice security-result"><p><strong>Secreto:</strong> {{twoFactor.secret}}</p><p><strong>URI:</strong> {{twoFactor.uri}}</p><small>Escanea la URI con tu aplicación autenticadora.</small><div class="inline-form"><input v-model="twoFactorToken" placeholder="Código de 6 dígitos"><button class="btn" @click="confirmTwoFactor">Confirmar código</button></div></div></section>
      <section v-else-if="section==='inventory'" class="panel inventory-module"><form class="card inventory-filter-card" @submit.prevent><div class="row"><label class="field"><span>Buscar producto</span><input v-model="inventoryFilters.search" placeholder="Código o nombre"></label><label class="field"><span>Stock desde</span><input v-model="inventoryFilters.stockFrom" type="number" min="0" step="0.01" placeholder="Ej. 0"></label><label class="field"><span>Stock hasta</span><input v-model="inventoryFilters.stockTo" type="number" min="0" step="0.01" placeholder="Ej. 10"></label><div class="field inventory-filter-action"><button class="btn secondary">Filtrar</button></div></div></form><div class="card inventory-table-card"><table><thead><tr><th>Código</th><th>Producto</th><th>Marca</th><th>Procedencia</th><th>Stock actual</th><th>Stock mínimo</th><th>Alerta</th><th>Acciones</th></tr></thead><tbody><tr v-for="p in inventory" :key="p.id"><td>{{p.code}}</td><td>{{p.name}}</td><td>—</td><td>—</td><td>{{p.stock}}</td><td>{{p.minStock}}</td><td>{{Number(p.stock)<=Number(p.minStock)?'Stock bajo':'—'}}</td><td class="row-actions"><button class="btn secondary" @click="select('products')">Ver</button><button class="btn secondary" @click="startCatalogEdit(p,'products')">Editar</button></td></tr><tr v-if="!inventory.length"><td colspan="8" class="muted">No existen productos en inventario.</td></tr></tbody></table></div></section>
      <section v-else-if="section==='lots'" class="panel"><div class="section-head"><div><p class="eyebrow">Control de inventario</p><h2>Lotes y vencimientos</h2></div><span class="pill" :class="expiringLots.length?'low':'ok'">{{expiringLots.length}} por vencer</span></div><form class="form-grid" @submit.prevent="lotEditing?saveLot():createLot"><select v-model="lotForm.productId" required><option value="">Producto</option><option v-for="p in products" :value="p.id" :key="p.id">{{p.code}} · {{p.name}}</option></select><input v-model="lotForm.code" placeholder="Código de lote" required><input v-model="lotForm.expiryDate" type="date"><input v-model.number="lotForm.quantity" type="number" min="0" step="0.001" placeholder="Cantidad" required><div class="actions"><button class="btn">{{lotEditing?'Guardar cambios':'Crear lote'}}</button><button v-if="lotEditing" type="button" class="btn secondary" @click="cancelLotEdit">Cancelar</button></div></form><table><thead><tr><th>Producto</th><th>Lote</th><th>Vencimiento</th><th>Cantidad</th><th>Estado</th><th>Acciones</th></tr></thead><tbody><tr v-for="lot in lots" :key="lot.id"><td>{{lot.product?.name}}</td><td>{{lot.code}}</td><td>{{lot.expiryDate?new Date(lot.expiryDate).toLocaleDateString('es-BO'):'Sin vencimiento'}}</td><td>{{lot.quantity}}</td><td><span class="pill" :class="lot.expiryDate && new Date(lot.expiryDate).getTime()<=Date.now()+30*86400000?'low':'ok'">{{lot.expiryDate && new Date(lot.expiryDate).getTime()<=Date.now()+30*86400000?'Alerta':'Vigente'}}</span></td><td class="row-actions"><button class="btn secondary" @click="startLotEdit(lot)">Editar</button><button class="btn danger" @click="deactivateLot(lot.id)">Desactivar</button></td></tr></tbody></table></section>
      <section v-else-if="section==='movements'" class="panel"><p class="eyebrow">Trazabilidad de existencias</p><h2>Kardex y ajustes manuales</h2><form class="form-grid" @submit.prevent="adjustInventory"><select v-model="adjustmentForm.productId" required><option value="">Producto</option><option v-for="p in products" :value="p.id" :key="p.id">{{p.code}} · {{p.name}}</option></select><select v-model="adjustmentForm.lotId"><option value="">Sin lote específico</option><option v-for="lot in lots.filter(l=>!adjustmentForm.productId || l.productId===Number(adjustmentForm.productId))" :value="lot.id" :key="lot.id">{{lot.code}} · {{lot.product?.name}}</option></select><select v-model="adjustmentForm.type"><option value="IN">Entrada</option><option value="OUT">Salida</option><option value="ADJUSTMENT">Ajuste</option></select><input v-model.number="adjustmentForm.quantity" type="number" min="0.001" step="0.001" placeholder="Cantidad" required><input v-model="adjustmentForm.reference" placeholder="Referencia"><button class="btn">Registrar movimiento</button></form><table><thead><tr><th>Fecha</th><th>Producto</th><th>Lote</th><th>Tipo</th><th>Cantidad</th><th>Referencia</th></tr></thead><tbody><tr v-for="m in movements" :key="m.id"><td>{{new Date(m.createdAt).toLocaleString('es-BO')}}</td><td>{{m.product?.name}}</td><td>{{m.lot?.code||'—'}}</td><td><span class="pill" :class="m.type==='OUT'?'low':m.type==='IN'?'ok':''">{{m.type==='OUT'?'Salida':m.type==='IN'?'Entrada':'Ajuste'}}</span></td><td>{{m.quantity}}</td><td>{{m.reference||'—'}}</td></tr></tbody></table></section>
      <section v-else class="panel operation-panel"><form class="card document-editor-card" @submit.prevent="createOperation(section)"><div class="section-head"><div><p class="eyebrow">{{section==='sale'?'Salida de inventario':'Entrada de inventario'}}</p><h2>{{section==='sale'?'Registro de ventas':'Registro de compras'}}</h2></div><div class="actions"><button type="button" class="btn secondary" @click="select(section==='sale'?'customers':'suppliers')">{{section==='sale'?'Crear cliente':'Crear proveedor'}}</button></div></div><div class="row"><label class="field"><span>Orden</span><select v-model="commercialName"><option>San Benjamin</option><option>Supra Medic</option></select></label><label class="field"><span>Tipo documento</span><select v-model="operationMeta.documentType"><option value="INVOICE">Factura</option><option value="DELIVERY_NOTE">Nota de entrega</option></select></label><label class="field"><span>Modalidad de stock</span><select v-model="operationMeta.stockMode"><option value="NORMAL">Stock normal</option><option value="PENDING">Stock pendiente</option></select></label><label class="field"><span>Fecha</span><input v-model="operationMeta.date" type="date"></label><label class="field"><span>Factura / nota</span><input v-model="operationMeta.invoice"></label><label class="field"><span>No.</span><input v-model="operationMeta.number" placeholder="Autogenerado"></label></div><section class="payment-plan"><div class="row"><label class="field"><span>Forma de pago</span><select v-model="operationMeta.paymentPlan"><option value="CASH">Pago único</option><option value="INSTALLMENTS">Pago en cuotas</option></select></label><label class="field"><span>{{section==='sale'?'Cliente':'Proveedor'}}</span><select v-model="operation.personId"><option value="">General</option><option v-for="r in (section==='sale'?customers:suppliers)" :value="r.id" :key="r.id">{{r.name}}</option></select></label></div></section><div class="card editor-items-card"><table><thead><tr><th>Producto</th><th>Cantidad</th><th>{{section==='sale'?'Precio':'Costo'}}</th><th>Subtotal</th><th></th></tr></thead><tbody><tr v-for="(item,index) in operation.items" :key="index"><td><select v-model="item.productId" required @change="item.price=Number(products.find(p=>p.id===Number(item.productId))?.[section==='sale'?'salePrice':'purchaseCost']||0)"><option value="">Seleccionar producto</option><option v-for="p in products" :value="p.id" :key="p.id">{{p.code}} · {{p.name}} (stock {{p.stock}})</option></select></td><td><input v-model.number="item.quantity" type="number" min="0.001" step="0.001" required></td><td><input v-model.number="item.price" type="number" min="0" step="0.01" required></td><td>Bs {{(Number(item.quantity||0)*Number(item.price||0)).toFixed(2)}}</td><td><button type="button" class="btn danger" @click="removeOperationItem(index)">Quitar</button></td></tr></tbody><tfoot><tr><th colspan="3" style="text-align:right">Total del documento</th><th>Bs {{operationTotal.toFixed(2)}}</th><th></th></tr></tfoot></table></div><div class="actions"><button type="button" class="btn secondary" @click="addOperationItem">Agregar producto</button><button class="btn">Confirmar {{section==='sale'?'venta':'compra'}}</button></div></form></section>
    <div v-if="!commercialConfirmed" class="commercial-overlay"><section class="glass-form commercial-form"><h1>Nombre comercial</h1><p>Seleccione con qué nombre comercial iniciará el dashboard.</p><div class="exchange-box"><span>Tipo de cambio del día</span><strong>Bs {{exchangeRate.toFixed(2)}}</strong></div><div class="commercial-options"><button type="button" :class="['commercial-option', {selected:commercialName==='San Benjamin'}]" @click="commercialName='San Benjamin'"><img src="/assets/logos/san-benjamin.png" alt="San Benjamin"><strong>San Benjamin</strong><small>NIT: 411168020</small></button><button type="button" :class="['commercial-option', {selected:commercialName==='Supra Medic'}]" @click="commercialName='Supra Medic'"><img src="/assets/logos/supra-medic.png" alt="Supra Medic"><strong>Supra Medic</strong><small>NIT: 1031388011</small></button></div><button class="continue-button" type="button" @click="confirmCommercial">Continuar</button></section></div>
    </main></div>
